import React, { useState } from 'react';

function MovieList({ movies, showtimes, onSelectMovie, onGoToAuth }) {
  const [searchTerm, setSearchTerm] = useState('');
  const [genre, setGenre] = useState('Tất Cả');
  const [maxPrice, setMaxPrice] = useState(130000);
  const [sortBy, setSortBy] = useState('default');

  const genres = ['Tất Cả', 'Hoạt Hình', 'Hành Động', 'Viễn Tưởng', 'Kinh Dị'];

  const getMinPrice = (movieId) => {
    const movieShowtimes = showtimes.filter((item) => item.movie_id === movieId);
    if (!movieShowtimes.length) return 0;
    return Math.min(...movieShowtimes.map((item) => item.ticket_price));
  };

  const filteredMovies = movies
    .filter((movie) => {
      const titleMatch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
      const genreMatch = genre === 'Tất Cả' || movie.genre === genre;
      const priceMatch = getMinPrice(movie.id) <= maxPrice;
      return titleMatch && genreMatch && priceMatch;
    })
    .sort((a, b) => {
      if (sortBy === 'duration') return b.duration - a.duration;
      if (sortBy === 'price-asc') return getMinPrice(a.id) - getMinPrice(b.id);
      if (sortBy === 'price-desc') return getMinPrice(b.id) - getMinPrice(a.id);
      return 0;
    });

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2 className="fw-bold text-dark text-uppercase m-0">🎬 Phim Đang Chiếu</h2>
        <button className="btn btn-outline-primary fw-bold" onClick={onGoToAuth}>Đăng Nhập / Đăng Ký</button>
      </div>

      <div className="card p-3 shadow-sm border-0 mb-4 bg-white">
        <div className="row g-3 align-items-center">
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary">Tìm kiếm tên phim</label>
            <input type="text" className="form-control" placeholder="Nhập tên phim..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary">Giá vé tối đa: <span className="text-danger">{maxPrice.toLocaleString()}đ</span></label>
            <input type="range" className="form-range" min="80000" max="130000" step="5000" value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} />
          </div>
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary">Sắp xếp theo</label>
            <select className="form-select" value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
              <option value="default">Mặc định</option>
              <option value="duration">Thời lượng (Giảm dần)</option>
              <option value="price-asc">Giá vé (Thấp đến Cao)</option>
              <option value="price-desc">Giá vé (Cao đến Thấp)</option>
            </select>
          </div>
        </div>
        <div className="mt-4 border-top pt-3">
          <div className="d-flex flex-wrap gap-2">
            {genres.map((genreItem) => (
              <button
                key={genreItem}
                className={`btn btn-sm px-3 py-2 rounded-pill fw-bold ${genre === genreItem ? 'btn-danger shadow' : 'btn-outline-secondary bg-light'}`}
                onClick={() => setGenre(genreItem)}
              >
                {genreItem}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="row">
        {filteredMovies.map((movie) => {
          const minPrice = getMinPrice(movie.id);
          return (
            <div className="col-12 col-sm-6 col-md-4 mb-4" key={movie.id}>
              <div className="card h-100 shadow border-0 overflow-hidden">
                <img src={movie.image_url} className="card-img-top" alt={movie.title} style={{ height: '360px', objectFit: 'cover' }} />
                <div className="card-body d-flex flex-column bg-white">
                  <h5 className="card-title fw-bold text-dark text-truncate">{movie.title}</h5>
                  <div className="d-flex gap-2 mb-2">
                    <span className="badge bg-secondary">⏱ {movie.duration} phút</span>
                    <span className="badge bg-info text-dark fw-bold">🏷 {movie.genre}</span>
                  </div>
                  <p className="card-text text-muted flex-grow-1" style={{ fontSize: '0.85rem' }}>{movie.description}</p>
                  <div className="border-top pt-2 mt-2 d-flex justify-content-between align-items-center">
                    <span className="text-secondary small">Giá chỉ từ:</span>
                    <strong className="text-danger fs-5">{minPrice > 0 ? `${minPrice.toLocaleString()}đ` : 'Hết vé'}</strong>
                  </div>
                  <button className="btn btn-danger w-100 fw-bold mt-3 py-2" onClick={() => onSelectMovie(movie)}>Mua Vé Ngay</button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default MovieList;
